<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/app/autoload.php';
use FMonitor2\InstallationProcess\JobsSchemaMigration;use FMonitor2\Jobs\{MariaDbWorkforceScheduler};
assertSameValue(true,class_exists(MariaDbWorkforceScheduler::class),'INTENTIONAL_RED: public Europe/Moscow workforce scheduler exists');
$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_scheduler_'.bin2hex(random_bytes(5));$admin=new mysqli($host,$user,$password,'',$port);$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$user,$password,$name,$port);$p='schedule_';$now='2026-09-09T07:03:00.000000Z';$barrier=sys_get_temp_dir().'/fm2-scheduler-race-'.bin2hex(random_bytes(5));mkdir($barrier,0700);$children=[];
try{
    JobsSchemaMigration::apply($db,$p);$scheduler=new MariaDbWorkforceScheduler($db,$p);
    $before=$scheduler->tick('2026-09-09T07:03:00.000000Z');assertSameValue(['slot'=>'2026-09-09T09','dueAt'=>'2026-09-09T06:07:00.000000Z','created'=>true],array_intersect_key($before,array_flip(['slot','dueAt','created'])),'10:03 Moscow selects previous 09:07 slot');$repeat=$scheduler->tick('2026-09-09T07:03:00.000000Z');assertSameValue($before['jobId'],$repeat['jobId'],'same slot tick is unique');
    $at=$scheduler->tick('2026-09-09T07:07:00.000000Z');assertSameValue('2026-09-09T10',$at['slot'],'10:07 Moscow selects current slot');$resume=$scheduler->tick('2026-09-09T11:20:00.000000Z');assertSameValue(['2026-09-09T14',3],[$resume['slot'],$resume['skippedSlots']],'14:20 resume enqueues latest only and records three skipped');
    $jobs=$db->query("SELECT job_type,payload_version,idempotency_key,payload_json FROM `{$p}fm2_jobs` ORDER BY job_id")->fetch_all(MYSQLI_ASSOC);assertSameValue(3,count($jobs),'no hourly burst backfill');$expected=[['2026-09-09T09','2026-09-09T06:07:00.000000Z','c3e263b2-0dff-43f9-82d6-dc9193f201e9'],['2026-09-09T10','2026-09-09T07:07:00.000000Z','027243e1-01f7-4ebd-a387-2facc0eb21ec'],['2026-09-09T14','2026-09-09T11:07:00.000000Z','b5728c62-4fbb-406f-ad9d-1eaa949801ba']];foreach($jobs as$i=>$job){$payload=json_decode($job['payload_json'],true,512,JSON_THROW_ON_ERROR);assertSameValue(['workforce.sync',1,$expected[$i][2],['dueAtUtc'=>$expected[$i][1],'runIdentity'=>$expected[$i][2],'scheduleSlot'=>$expected[$i][0]]],[$job['job_type'],(int)$job['payload_version'],$job['idempotency_key'],$payload],'scheduler exact type/version/idempotency/payload identity');}
    foreach([1,2]as$i){$arrival="$barrier/arrival-$i";$process=proc_open([PHP_BINARY,dirname(__DIR__).'/Support/jobs_scheduler_worker.php',$name,$p,"scheduler-$i",$arrival,"$barrier/release",str_repeat((string)($i+3),64)],[0=>['file','/dev/null','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2),array_replace(getenv(),['FMONITOR_TEST_DB_ADMIN_PASSWORD'=>$password]));if(!is_resource($process))throw new TestFailure('SETUP_FAILURE scheduler child');$children[]=[$process,$pipes,$arrival];}
    $deadline=microtime(true)+5;while((!is_file($children[0][2])||!is_file($children[1][2]))&&microtime(true)<$deadline)usleep(1000);assertSameValue(true,is_file($children[0][2])&&is_file($children[1][2]),'both scheduler children connected before tick');file_put_contents("$barrier/release","go\n",LOCK_EX);$results=[];foreach($children as[$process,$pipes]){stream_set_timeout($pipes[1],10);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);$timed=stream_get_meta_data($pipes[1])['timed_out'];fclose($pipes[1]);fclose($pipes[2]);if($timed)proc_terminate($process,9);assertSameValue([false,0,''],[$timed,proc_close($process),$err],'bounded scheduler child');$results[]=json_decode(trim($out),true,512,JSON_THROW_ON_ERROR);}$ids=array_unique(array_column($results,'jobId'));$created=array_column($results,'created');sort($created);assertSameValue([1,[false,true]],[count($ids),$created],'concurrent same-slot ticks return one job and one creator');$raceJob=$db->query("SELECT idempotency_key,payload_json FROM `{$p}fm2_jobs` WHERE idempotency_key='d7f57de3-20d1-441b-94f6-f2ddc79625a2'")->fetch_assoc();assertSameValue(['d7f57de3-20d1-441b-94f6-f2ddc79625a2',['dueAtUtc'=>'2026-09-09T12:07:00.000000Z','runIdentity'=>'d7f57de3-20d1-441b-94f6-f2ddc79625a2','scheduleSlot'=>'2026-09-09T15']],[$raceJob['idempotency_key'],json_decode($raceJob['payload_json'],true,512,JSON_THROW_ON_ERROR)],'concurrent slot exact idempotency and payload');assertSameValue(1,(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_scheduler_slots` WHERE schedule_key='workforce-hourly-v1/2026-09-09T15'")->fetch_assoc()['n'],'concurrent tick persists one schedule slot');echo"PASS: DURABLE-BACKGROUND-JOBS-001 workforce Moscow schedule\n";
}finally{foreach($children as[$process])if(is_resource($process)){proc_terminate($process,9);proc_close($process);}foreach(glob("$barrier/*")?:[]as$file)unlink($file);rmdir($barrier);$db->close();$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}
